const pattern = (name) => new RegExp('(\\b' + name + '\\s*=\\s*(?:wxT\\()?\\s*")(iVBORw0KGgo[^"]*)(")');
const gridOf = (svg) => Number(/viewBox='0 0 (\d+) /.exec(svg)[1]);

function renderPng(svg, px) {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'oes-pic-'));
  const html = path.join(tmp, 'p.html'), png = path.join(tmp, 'p.png');
  fs.writeFileSync(html, "<!doctype html><html><body style='margin:0;background:transparent'>" +
    `<img width='${px}' height='${px}' style='display:block' src="data:image/svg+xml;utf8,${encodeURIComponent(svg)}"></body></html>`);
  execFileSync(EDGE, ['--headless=new', '--disable-gpu', '--hide-scrollbars', '--default-background-color=00000000',
    '--force-device-scale-factor=1', `--window-size=${px},${px}`, `--screenshot=${png}`, 'file:///' + html.replace(/\\/g, '/')], { stdio: 'ignore' });
  const out = fs.readFileSync(png);
  fs.rmSync(tmp, { recursive: true, force: true });
  if (out.readUInt32BE(16) !== px || out.readUInt32BE(20) !== px) throw new Error(`rendered ${out.readUInt32BE(16)}x${out.readUInt32BE(20)}, wanted ${px}`);
  return out;
}

const args = process.argv.slice(2), check = args.includes('--check'), only = args.filter((a) => !a.startsWith('--'));
const files = {}, drawn = {};
let problems = 0;
for (const t of TARGETS) {
  if (only.length && !only.includes(t.svg) && !only.includes(t.name)) continue;
  const file = path.join(ENGINE, t.file);
  if (!fs.existsSync(file)) { console.log(`NO FILE    ${t.file}`); problems++; continue; }
  const src = files[file] = files[file] || fs.readFileSync(file, 'utf8');
  if (!pattern(t.name).test(src)) { console.log(`NOT FOUND  ${t.file}: ${t.name}`); problems++; continue; }
  const svg = SOURCES[t.svg];
  if (!svg) { console.log(`NO SOURCE  ${t.svg} for ${t.name}`); problems++; continue; }
  const px = gridOf(svg) * SCALE;
  if (check) { console.log(`ok         ${t.name} ${px}px <- ${t.svg}`); continue; }
  const b64 = drawn[t.svg] = drawn[t.svg] || renderPng(svg, px).toString('base64');
  files[file] = src.replace(pattern(t.name), (all, a, b, c) => a + b64 + c);
  console.log(`drawn      ${t.name} ${px}px <- ${t.svg}`);
}
if (!check) for (const [file, src] of Object.entries(files)) fs.writeFileSync(file, src);
process.exit(problems ? 1 : 0);
